      case 'rg':         cmdRg(rest); break;
      case 'read':       cmdRead(rest); break;
      case 'status':     cmdStatus(rest); break;
      default:
        throw new Error(unknownCommandMessage(cmd));
    }
  } catch (err) {
    const normalized = normalizeCliError(err);
    console.error(normalized.message);
